@push('scripts')<script>document.querySelectorAll('form[action$="circuits"]').forEach(form=>form.addEventListener('submit',()=>{const textarea=form.querySelector('#legs-text');textarea.value.trim().split(/\n+/).forEach((line,index)=>{const [departure,arrival]=line.split(',').map(v=>v.trim()); for(const [key,value] of [['departure',departure],['arrival',arrival]]){const input=document.createElement('input');input.type='hidden';input.name=`legs[${index}][${key}]`;input.value=value||'';form.append(input)}})}));</script>@endpush
